// Resolve the ACTUAL province of a coordinate via nearest district — more accurate
// than province centroids since districts stay inside one province
export function findActualProvince(lat, lng) {
  let best = null, bestDist = Infinity;
  for (const p of TH_ADMIN) {
    for (const d of p.districts) {
      if (d.lat == null) continue;
      const dist = calculateDistanceKm(lat, lng, d.lat, d.lng);
      if (dist < bestDist) { bestDist = dist; best = { province: p.province, provinceEn: p.provinceEn, district: d, distanceKm: dist }; }
    }
  }
  return best;
}

// Search provinces/districts by th or en text (live suggestions + submit)
// Order: matching provinces → prefix-matched districts → substring matches
export function searchAdmin(q) {
  const bare = q.toLowerCase().trim();
  const provs = [], first = [], rest = [];
  const hit = (th, en) => th.includes(bare) || (en && en.toLowerCase().includes(bare));
  const starts = (th, en) => th.startsWith(bare) || (en && en.toLowerCase().startsWith(bare));
  for (const p of TH_ADMIN) {
    if (hit(p.province, p.provinceEn)) {
      provs.push({ label: `${p.provinceEn} Province`, lat: null, lng: null, province: p.province, provinceEn: p.provinceEn });
    }
    for (const d of p.districts) {
      if (!hit(d.name, d.nameEn)) continue;
      const item = { label: `${d.prefixEn} ${d.nameEn}, ${p.provinceEn}`, lat: d.lat, lng: d.lng, province: p.province, provinceEn: p.provinceEn, district: d };
      (starts(d.name, d.nameEn) ? first : rest).push(item);
    }
  }
  return [...provs, ...first, ...rest];
}
